    },
    {
      "scene_number": 3,
      "caption": "The scout spots an armored patrol on the main road.",
      "visual_description": "Three figures in dark plate armor march in formation, shields bearing a faded crest. Dust rises from their boots.",
      "characters": ["scout", "armored_patrol"]
    },
    {
      "scene_number": 4,
      "caption": "The team takes a hidden alley to avoid patrols.",
      "visual_description": "Narrow passage flanked by crumbling walls. A brass compass glints in the map reader's hand.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 5,
      "caption": "They reach a cursed tower with a strange door.",
      "visual_description": "A spiral tower of black stone. The door is covered in glowing runes that pulse slowly.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 6,
      "caption": "The magic door opens with a crystal key.",
