      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 7,
      "caption": "Inside, they find a mirror hall of illusions.",
      "visual_description": "Tall mirrors line a circular chamber, each reflecting a different ruined scene. A single torch flickers at the center.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "The scout hears rumors of a dragon from a hidden prisoner.",
      "visual_description": "A barred cell in the tower wall. Inside, a gaunt figure clutches a torn banner and mutters about wings.",
      "characters": ["scout", "hidden_prisoner"]
    },
    {
      "scene_number": 9,
      "caption": "They climb a broken spiral stair to the tower top.",
      "visual_description": "Stone steps slick with moss. Arrow slits show grey sky. Old royal banners drape from upper walls.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "The prisoner is freed and joins the team.",
      "visual_description": "The map reader turns the crystal key in a lock. The cell door swings open. The prisoner steps out, blinking.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols block the tower exit.",
      "visual_description": "Six armored figures stand in formation outside the tower door, swords drawn. Torchlight glints on their helms.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner", "armored_patrol"]
    },
    {
      "scene_number": 12,
      "caption": "The magic helper casts a blinding light.",
      "visual_description": "A burst of white light erupts from the magic_helper's hands. The patrol shields their eyes and staggers back.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner", "armored_patrol"]
    },
    {
      "scene_number": 13,
      "caption": "They dash through an old plaza under torn banners.",
      "visual_description": "Broad plaza with a cracked fountain at center. Faded royal banners hang from surrounding columns. Rubble litters the ground.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "The scout spots the bridge control mechanism.",
      "visual_description": "A stone lever housing at the plaza edge. A rusted chain descends into a dark slot. A mirror shard is wedged near the lever.",
      "characters": ["scout", "map_reader"]
    },
    {
      "scene_number": 15,
      "caption": "They activate the bridge lever together.",
      "visual_description": "The map reader and scout pull the lever down. The chain rattles and a deep rumble shakes the ground.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "The escape bridge lowers across a chasm.",
      "visual_description": "A massive stone bridge descends from a raised position, grinding against weathered gears. Mist fills the gorge below.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols pursue them onto the bridge.",
      "visual_description": "The team runs across the bridge. Behind them, armored figures pour onto the stone. A dragon silhouette circles in the distant sky.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner", "armored_patrol"]
    },
    {
      "scene_number": 18,
      "caption": "They cross safely and the bridge collapses behind.",
      "visual_description": "The team reaches the far side. The bridge cracks and falls into the gorge in a cloud of dust. The ruined city is now cut off.",
      "characters": ["map_reader", "scout", "magic_helper", "hidden_prisoner"]
    }
  ]
}
```

